CREATE TABLE faculties (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,UNIQUE(org_id,name),FOREIGN KEY(org_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE programs (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,faculty_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,UNIQUE(faculty_id,name),FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(faculty_id) REFERENCES faculties(id)) ENGINE=InnoDB;
ALTER TABLE grades ADD COLUMN program_id CHAR(36) NULL,ADD COLUMN program_scope VARCHAR(36) GENERATED ALWAYS AS (COALESCE(program_id,'')) STORED,ADD INDEX idx_grade_org(org_id),DROP INDEX org_id,ADD UNIQUE KEY uq_grade_scope(org_id,program_scope,name),ADD FOREIGN KEY(program_id) REFERENCES programs(id);
ALTER TABLE batches ADD COLUMN academic_year VARCHAR(40) NOT NULL DEFAULT '';
CREATE TABLE course_units (id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,title VARCHAR(160) NOT NULL,position INT NOT NULL DEFAULT 1,objectives TEXT NOT NULL,content MEDIUMTEXT NOT NULL,lesson_plan MEDIUMTEXT NOT NULL,duration_minutes INT NOT NULL DEFAULT 45,status ENUM('draft','published') NOT NULL DEFAULT 'draft',quiz JSON NOT NULL,quiz_revision CHAR(36) NOT NULL,version INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE unit_quiz_attempts (id CHAR(36) PRIMARY KEY,unit_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,quiz_revision CHAR(36) NOT NULL,score INT NOT NULL,answers JSON NOT NULL,submitted_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX(unit_id,user_id),FOREIGN KEY(unit_id) REFERENCES course_units(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE unit_completions (unit_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,completed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(unit_id,user_id),FOREIGN KEY(unit_id) REFERENCES course_units(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
ALTER TABLE course_materials ADD COLUMN unit_id CHAR(36) NULL,ADD FOREIGN KEY(unit_id) REFERENCES course_units(id) ON DELETE CASCADE;
ALTER TABLE assessments MODIFY kind ENUM('project','assignment','worksheet','case_study') NOT NULL,ADD COLUMN unit_id CHAR(36) NULL,ADD COLUMN case_context TEXT NULL,ADD COLUMN deliverables TEXT NULL,ADD COLUMN rubric TEXT NULL,ADD FOREIGN KEY(unit_id) REFERENCES course_units(id) ON DELETE CASCADE;
CREATE TABLE attendance_sessions (id CHAR(36) PRIMARY KEY,batch_id CHAR(36) NOT NULL,subject_id CHAR(36) NOT NULL,session_date DATE NOT NULL,period INT NOT NULL,topic VARCHAR(200) NOT NULL DEFAULT '',version INT NOT NULL DEFAULT 1,updated_by CHAR(36) NOT NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(batch_id,subject_id,session_date,period),FOREIGN KEY(batch_id) REFERENCES batches(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(updated_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE attendance_records (session_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,status ENUM('present','absent','late','excused','unmarked') NOT NULL,remark VARCHAR(300) NOT NULL DEFAULT '',PRIMARY KEY(session_id,user_id),FOREIGN KEY(session_id) REFERENCES attendance_sessions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
